// REPORT ONLY. No prune. No delete. No n8n_data wipe. No docker volume rm.
// Watchdog VPS script is the sensor; this n8n row registers the alert for Grok.
const body = ($json && ($json.body || $json)) || {};
const diskPct = Number(body.diskPct || body.disk_pct || body.percent || 0);
const host = body.host || 'evenslouis.ca';
const correlationId = body.correlationId || `disk-${Date.now()}`;
const level = diskPct >= 90 ? 'CRITICAL' : diskPct >= 85 ? 'WARN' : 'INFO';

const summary = diskPct
  ? `VPS disk ${diskPct}% on ${host} — operator prune required if >=90. n8n must not delete.`
  : `hive-disk-alert stub tick — no df from this node. Prefer scripts/hive/hive-watchdog.sh disk check.`;

return [{
  json: {
    correlationId,
    diskPct,
    host,
    level,
    prune: false,
    delete: false,
    registerPayload: {
      correlationId,
      jobType: 'hive.disk.alert',
      goal: 'Report disk pressure to Scorpion / Grok Watchdog — no prune',
      source: 'hive-disk-alert',
      status: level === 'CRITICAL' ? 'need_hitl' : 'done',
      registerTo: 'scorpion',
      summary,
      metadata: {
        lane: 'hive-os',
        diskPct: String(diskPct || 'unknown'),
        prune: 'never',
        delete: 'never',
        telegramRequired: 'false',
        philanthropyHold: 'true',
        openclawHold: 'true'
      }
    }
  }
}];

// Cron ticks must not hit respondToWebhook (no inbound webhook).
let fromWebhook = false;
try {
  const w = $('Disk Alert Webhook').first();
  fromWebhook = !!(w && w.json);
} catch (e) {
  fromWebhook = false;
}
return [{ json: { ...$json, fromWebhook } }];
